"use client";

import { useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import Hero from "./Hero";
import ComparisonGrid from "./ComparisonGrid";
import LearnGrid from "./LearnGrid";
import FeaturedComparison from "./FeaturedComparison";
import { comparisons, type CategoryId } from "@/lib/data";

export default function HomeClient() {
  const [query, setQuery] = useState("");
  const router = useRouter();

  const handleSearch = (e: FormEvent) => {
    e.preventDefault();
    const keyword = query.trim();
    if (!keyword) {
      router.push("/compare");
      return;
    }
    router.push(`/compare?q=${encodeURIComponent(keyword)}`);
  };

  const goCategory = (category: CategoryId) => {
    router.push(`/category/${category}`);
  };

  const searchExample = (term: string) => {
    setQuery(term);
    router.push(`/compare?q=${encodeURIComponent(term)}`);
  };

  return (
    <main>
      <Hero
        query={query}
        onQueryChange={setQuery}
        onSearch={handleSearch}
        onQuickCategory={goCategory}
        onExampleSearch={searchExample}
      />
      <ComparisonGrid items={comparisons} />
      <LearnGrid />
      <FeaturedComparison />
    </main>
  );
}
